// frontend/src/pages/AdminDashboard.tsx
import React, { useEffect, useState } from "react";
import api from "../api";
import CreateUserForm from "../pages/CreateUserForm";

interface User {
  _id: string;
  firstName: string;
  lastName: string;
  email: string;
  role: string;
  departments: string[];
  createdAt: string;
}

interface SimpleUserRef {
  _id: string;
  firstName: string;
  lastName: string;
  email: string;
  role: string;
}

interface Ticket {
  _id: string;
  title: string;
  status: "open" | "in_progress" | "closed";
  category: "billing" | "technical" | "general";
  priority: "low" | "medium" | "high";
  createdBy: SimpleUserRef;
  assignee?: SimpleUserRef | null;
  createdAt: string;
}

interface Props {
  name: string;
}

const AdminDashboard: React.FC<Props> = ({ name }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [loadingUsers, setLoadingUsers] = useState(true);

  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [loadingTickets, setLoadingTickets] = useState(true);

  const [showCreateForm, setShowCreateForm] = useState(false);

  const fetchUsers = async () => {
    try {
      const res = await api.get<User[]>("/admin/users");
      setUsers(res.data);
    } catch (err) {
      console.error("Failed to fetch users", err);
    } finally {
      setLoadingUsers(false);
    }
  };

  const fetchTickets = async () => {
    try {
      const res = await api.get<Ticket[]>("/admin/tickets");
      setTickets(res.data);
    } catch (err) {
      console.error("Failed to fetch tickets", err);
    } finally {
      setLoadingTickets(false);
    }
  };

  useEffect(() => {
    // load both in parallel on first render
    fetchUsers();
    fetchTickets();
  }, []);

  return (
    <div>
      <h2>Welcome, Admin {name}</h2>

      {/* --- User management --- */}
      <h3>User Management</h3>
      <button onClick={() => setShowCreateForm(true)}>Create New User</button>

      {showCreateForm && (
        <div
          style={{ border: "1px solid black", padding: "10px", width: "300px" }}
        >
          <CreateUserForm
            onClose={() => setShowCreateForm(false)}
            onCreated={fetchUsers}
          />
        </div>
      )}

      {loadingUsers ? (
        <p>Loading users...</p>
      ) : (
        <table border={1} cellPadding={8} style={{ marginTop: "15px" }}>
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Role</th>
              <th>Departments</th>
              <th>Created</th>
            </tr>
          </thead>

          <tbody>
            {users.map((u) => (
              <tr key={u._id}>
                <td>
                  {u.firstName} {u.lastName}
                </td>
                <td>{u.email}</td>
                <td>{u.role}</td>
                <td>{u.departments.join(", ")}</td>
                <td>{new Date(u.createdAt).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* --- Tickets management (read-only for now) --- */}
      <h3 style={{ marginTop: "30px" }}>All Tickets</h3>

      {loadingTickets ? (
        <p>Loading tickets...</p>
      ) : tickets.length === 0 ? (
        <p>No tickets found.</p>
      ) : (
        <table border={1} cellPadding={8} style={{ marginTop: "10px" }}>
          <thead>
            <tr>
              <th>Title</th>
              <th>Status</th>
              <th>Priority</th>
              <th>Category</th>
              <th>Created By</th>
              <th>Assignee</th>
              <th>Created</th>
            </tr>
          </thead>
          <tbody>
            {tickets.map((t) => (
              <tr key={t._id}>
                <td>{t.title}</td>
                <td>{t.status}</td>
                <td>{t.priority}</td>
                <td>{t.category}</td>
                <td>
                  {t.createdBy
                    ? `${t.createdBy.firstName} ${t.createdBy.lastName}`
                    : "-"}
                </td>
                <td>
                  {t.assignee
                    ? `${t.assignee.firstName} ${t.assignee.lastName}`
                    : "-"}
                </td>
                <td>{new Date(t.createdAt).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default AdminDashboard;
